import type {
  ServiceInvoiceInput,
  ServiceInvoiceReading,
  ServiceInvoiceSyncItem,
} from './serviceInvoice.types';

export type PendingServiceInvoiceFile = {
  name: string;
  mimeType: string;
  bytesSize: number;
  /** Lowercase hex SHA-256, the shape the backend validates. */
  hash: string;
};

export type PendingServiceInvoice = {
  /** Generated by the app (ADR-09): the note has its identity before it syncs. */
  id: string;
  issueDate: string;
  amount: number;
  number?: string;
  /** May be the local id of a taker registered offline, resolved on sync. */
  clientId: string;
  file: PendingServiceInvoiceFile;
  createdAt: string;
  /** Refused for good: it stays queued, with its PDF, and is not sent again. */
  rejection?: { code: string | null; acknowledged: boolean };
};

/** Typed and read values that differ, kept for the person to confirm later. */
export type ReadingDifference = {
  invoiceId: string;
  typed: ServiceInvoiceReading;
  read: ServiceInvoiceReading;
};

/** Refusals the app tells apart; any other code is told in general terms. */
export const KNOWN_REJECTION_CODES = [
  'SERVICE_INVOICE_FILE_DUPLICATED',
  'SERVICE_INVOICE_FILE_TOO_LARGE',
  'CLIENT_NOT_SYNCED',
  'PENDING_FILE_MISSING',
] as const;

export type KnownRejectionCode = (typeof KNOWN_REJECTION_CODES)[number];

export const CLIENT_NOT_SYNCED: KnownRejectionCode = 'CLIENT_NOT_SYNCED';
export const PENDING_FILE_MISSING: KnownRejectionCode = 'PENDING_FILE_MISSING';

export function isKnownRejectionCode(
  code: string | null,
): code is KnownRejectionCode {
  return KNOWN_REJECTION_CODES.some(known => known === code);
}

export type PendingCounts = { waiting: number; rejected: number };

export function toPendingServiceInvoice(
  id: string,
  input: ServiceInvoiceInput,
  file: PendingServiceInvoiceFile,
  createdAt: string,
): PendingServiceInvoice {
  return {
    id,
    issueDate: input.issueDate,
    amount: input.amount,
    ...(input.number !== undefined ? { number: input.number } : {}),
    clientId: input.clientId,
    file,
    createdAt,
  };
}

export function toSyncItem(
  invoice: PendingServiceInvoice,
  clientId: string,
): ServiceInvoiceSyncItem {
  return {
    id: invoice.id,
    issueDate: invoice.issueDate,
    amount: invoice.amount,
    ...(invoice.number !== undefined ? { number: invoice.number } : {}),
    clientId,
    fileName: invoice.file.name,
    fileHash: invoice.file.hash,
    fileBytesSize: invoice.file.bytesSize,
  };
}

export function countPending(queue: PendingServiceInvoice[]): PendingCounts {
  const rejected = queue.filter(invoice => invoice.rejection).length;
  return { waiting: queue.length - rejected, rejected };
}

export function nextToSend(
  queue: PendingServiceInvoice[],
  attempted: ReadonlySet<string>,
): PendingServiceInvoice | undefined {
  return queue.find(
    invoice => !invoice.rejection && !attempted.has(invoice.id),
  );
}

export function firstRejection(
  queue: PendingServiceInvoice[],
): PendingServiceInvoice | null {
  return queue.find(invoice => invoice.rejection) ?? null;
}

export function firstUnseenRejection(
  queue: PendingServiceInvoice[],
): PendingServiceInvoice | null {
  return (
    queue.find(
      invoice => invoice.rejection && !invoice.rejection.acknowledged,
    ) ?? null
  );
}

/**
 * What the reading found that the person did not type. A field the reading
 * missed is not a difference, and neither is one it read the same.
 */
export function readingDifference(
  invoice: PendingServiceInvoice,
  reading: ServiceInvoiceReading | undefined,
): ReadingDifference | null {
  if (!reading) return null;

  const typed: ServiceInvoiceReading = {};
  const read: ServiceInvoiceReading = {};
  const fields = ['issueDate', 'amount', 'number'] as const;
  for (const field of fields) {
    const found = reading[field];
    if (found === undefined || found === invoice[field]) continue;
    Object.assign(read, { [field]: found });
    Object.assign(typed, { [field]: invoice[field] });
  }

  return Object.keys(read).length > 0
    ? { invoiceId: invoice.id, typed, read }
    : null;
}
